-- SCRIPT 07: PRUEBA INTEGRAL Y CARGA MASIVA DE 12,000 REGISTROS (T-SQL DIRECTO)
-- ==============================================================================
USE DM_Rapel_ComercioExterior;
GO

SET NOCOUNT ON;

PRINT 'Limpiando tabla stg.SUNAT_Export...';
TRUNCATE TABLE stg.SUNAT_Export;

PRINT 'Insertando 12,000 registros en lotes de 1,000 filas...';

PRINT 'Lote insertado: 1000 / 12000 filas...';

PRINT 'Lote insertado: 2000 / 12000 filas...';

PRINT 'Lote insertado: 3000 / 12000 filas...';

PRINT 'Lote insertado: 4000 / 12000 filas...';

PRINT 'Lote insertado: 5000 / 12000 filas...';

PRINT 'Lote insertado: 6000 / 12000 filas...';

PRINT 'Lote insertado: 7000 / 12000 filas...';

PRINT 'Lote insertado: 8000 / 12000 filas...';

PRINT 'Lote insertado: 9000 / 12000 filas...';

PRINT 'Lote insertado: 10000 / 12000 filas...';

PRINT 'Lote insertado: 11000 / 12000 filas...';

PRINT 'Lote insertado: 12000 / 12000 filas...';


-- 2. Verificación de la carga en Staging
SELECT COUNT(1) AS [Total Filas en Staging] FROM stg.SUNAT_Export;
GO

-- 3. Ejecutar el procedimiento ETL del Data Mart
PRINT 'Ejecutando procedimiento ETL: dm.usp_CargarDataMartComercial...';
EXEC dm.usp_CargarDataMartComercial;
GO

-- 4. Comprobación de auditoría y hechos
SELECT TOP 1 IdCarga, Estado, FilasStaging, FilasBuenas, FilasRechazadas, FechaInicio, FechaFin FROM audit.BitacoraCarga ORDER BY IdCarga DESC;
SELECT COUNT(1) AS [Total en Fact_ExportacionComercial] FROM dm.Fact_ExportacionComercial;
SELECT TOP 10 MotivoRechazo, COUNT(1) AS Cantidad FROM audit.FilasRechazadas GROUP BY MotivoRechazo;
GO
